-- Edel Solingen: SKUs das pinças douradas (PIN-DOU-PF/PO/PR) e fotos
UPDATE "products" SET "sku" = 'PIN-DOU-PF', "updatedAt" = now()
 WHERE "sku" = 'PIN-007' AND NOT EXISTS (SELECT 1 FROM "products" WHERE "sku" = 'PIN-DOU-PF');
INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'edel-pinca-dourada-ponta-fina.webp', 'image/webp', 2522, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'edel-pinca-dourada-ponta-fina.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'edel-pinca-dourada-ponta-fina.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'PIN-DOU-PF' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
